  <link rel="stylesheet" href="shared.css" />
  <style>
    /* ===== HERO ===== */
    .hero {
      background: linear-gradient(135deg, #0F1E3C 0%, #1a3060 60%, #0F1E3C 100%);
      padding: 120px 0 100px;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -200px; right: -200px;
      width: 600px; height: 600px;
      background: radial-gradient(circle, rgba(249,115,22,0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px; left: -100px;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(249,115,22,0.08) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero-inner {
      position: relative; z-index: 1;
      max-width: 860px;
    }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(249,115,22,0.15);
      border: 1px solid rgba(249,115,22,0.3);
      color: #FB923C;
      font-size: 0.8rem; font-weight: 600;
      letter-spacing: 0.08em; text-transform: uppercase;
      padding: 6px 16px; border-radius: 100px;
      margin-bottom: 28px;
    }
    .hero h1 {
      font-size: clamp(2.4rem, 5vw, 4rem);
      font-weight: 800;
      line-height: 1.1;
      color: #fff;
      margin-bottom: 24px;
    }
    .hero h1 span { color: #F97316; }
    .hero p {
      font-size: 1.2rem;
      color: rgba(255,255,255,0.72);
      max-width: 600px;
      line-height: 1.75;
      margin-bottom: 40px;
    }
    .hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }

    /* ===== STATS BANNER ===== */
    .stats-section {
      background: #fff;
      border-bottom: 1px solid #E8EBF0;
      padding: 64px 0;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      text-align: center;
    }
    .stat-item {}
    .stat-number {
      font-family: 'Space Grotesk', sans-serif;
      font-size: 2.8rem;
      font-weight: 800;
      color: #0F1E3C;
      line-height: 1;
      margin-bottom: 8px;
    }
    .stat-number span { color: #F97316; }
    .stat-label {
      font-size: 0.9rem;
      color: #6B7A94;
      font-weight: 500;
    }

    /* ===== FEATURES ===== */
    .features-section {
      background: #F8F9FC;
      padding: 100px 0;
    }
    .features-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
      margin-top: 60px;
    }
    .feature-card {
      background: #fff;
      border-radius: 16px;
      padding: 36px 32px;
      border: 1px solid #E8EBF0;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }
    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 16px 40px rgba(15,30,60,0.1);
    }
    .feature-icon {
      width: 52px; height: 52px;
      background: linear-gradient(135deg, #FEF3E8, #FDE4C8);
      border-radius: 14px;
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 20px;
      font-size: 1.5rem;
    }
    .feature-card h3 {
      font-size: 1.15rem;
      font-weight: 700;
      color: #0F1E3C;
      margin-bottom: 10px;
    }
    .feature-card p {
      font-size: 0.95rem;
      color: #6B7A94;
      line-height: 1.7;
    }

    /* ===== HOW IT WORKS ===== */
    .how-section {
      padding: 100px 0;
      background: #fff;
    }
    .how-steps {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      margin-top: 60px;
      position: relative;
    }
    .how-steps::before {
      content: '';
      position: absolute;
      top: 28px; left: calc(12.5% + 16px); right: calc(12.5% + 16px);
      height: 2px;
      background: linear-gradient(90deg, #F97316, #FB923C);
      z-index: 0;
    }
    .step {
      text-align: center;
      position: relative; z-index: 1;
    }
    .step-num {
      width: 56px; height: 56px;
      background: #F97316;
      color: #fff;
      border-radius: 50%;
      font-family: 'Space Grotesk', sans-serif;
      font-weight: 800;
      font-size: 1.3rem;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 20px;
      box-shadow: 0 4px 16px rgba(249,115,22,0.35);
    }
    .step h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: #0F1E3C;
      margin-bottom: 10px;
    }
    .step p { font-size: 0.9rem; color: #6B7A94; line-height: 1.65; }

    /* ===== TESTIMONIALS ===== */
    .testimonials-section {
      background: linear-gradient(135deg, #0F1E3C 0%, #1a3060 100%);
      padding: 100px 0;
    }
    .testimonial-carousel { position: relative; overflow: hidden; margin-top: 60px; }
    .testimonial-track {
      display: flex;
      transition: transform 0.4s cubic-bezier(0.4,0,0.2,1);
    }
    .testimonial-slide {
      min-width: 100%;
      padding: 0 60px;
      box-sizing: border-box;
    }
    .testimonial-card {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 20px;
      padding: 48px;
      max-width: 760px;
      margin: 0 auto;
      position: relative;
    }
    .testimonial-card::before {
      content: '"';
      font-size: 8rem;
      line-height: 1;
      color: #F97316;
      position: absolute;
      top: -20px; left: 40px;
      font-family: 'Space Grotesk', sans-serif;
      opacity: 0.4;
    }
    .testimonial-text {
      font-size: 1.2rem;
      color: rgba(255,255,255,0.9);
      line-height: 1.8;
      margin-bottom: 28px;
      position: relative; z-index: 1;
      font-style: italic;
    }
    .testimonial-author { display: flex; align-items: center; gap: 16px; }
    .author-avatar {
      width: 52px; height: 52px;
      border-radius: 50%;
      background: linear-gradient(135deg, #F97316, #EA580C);
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; font-size: 1.2rem; color: #fff;
      flex-shrink: 0;
