    .author-name { font-weight: 700; color: #fff; font-size: 1rem; }
    .author-title { font-size: 0.85rem; color: rgba(255,255,255,0.55); margin-top: 2px; }
    .carousel-controls {
      display: flex; align-items: center; justify-content: center;
      gap: 16px; margin-top: 36px;
    }
    .carousel-btn {
      width: 48px; height: 48px;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 50%;
      cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      transition: all 0.2s ease;
      color: #fff;
    }
    .carousel-btn:hover { background: #F97316; border-color: #F97316; }
    .carousel-dots { display: flex; gap: 8px; }
    .carousel-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: rgba(255,255,255,0.3);
      transition: all 0.2s;
      cursor: pointer;
    }
    .carousel-dot.active { background: #F97316; width: 24px; border-radius: 4px; }

    /* ===== PRICING TEASER ===== */
    .pricing-teaser {
      background: #F8F9FC;
      padding: 100px 0;
    }
    .pricing-cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
      margin-top: 60px;
    }
    .price-card {
      background: #fff;
      border-radius: 20px;
      padding: 40px 32px;
      border: 2px solid #E8EBF0;
      transition: all 0.2s;
    }
    .price-card:hover { border-color: #F97316; transform: translateY(-4px); }
    .price-card.featured {
      background: #0F1E3C;
      border-color: #F97316;
      transform: scale(1.04);
    }
    .price-card.featured:hover { transform: scale(1.04) translateY(-4px); }
    .plan-name {
      font-size: 0.8rem; font-weight: 700;
      text-transform: uppercase; letter-spacing: 0.08em;
      color: #F97316;
      margin-bottom: 12px;
    }
    .plan-price {
      font-family: 'Space Grotesk', sans-serif;
      font-size: 2.8rem;
      font-weight: 800;
      color: #0F1E3C;
      line-height: 1;
      margin-bottom: 6px;
    }
    .price-card.featured .plan-price { color: #fff; }
    .plan-period { font-size: 0.9rem; color: #9CA6B8; margin-bottom: 24px; }
    .price-card.featured .plan-period { color: rgba(255,255,255,0.5); }
    .plan-desc {
      font-size: 0.95rem; color: #6B7A94; margin-bottom: 28px; line-height: 1.6;
    }
    .price-card.featured .plan-desc { color: rgba(255,255,255,0.65); }
    .plan-link {
      display: block; text-align: center;
      padding: 12px 24px;
      border-radius: 10px;
      font-weight: 600; font-size: 0.95rem;
      text-decoration: none;
      transition: all 0.2s;
      border: 2px solid #E8EBF0;
      color: #0F1E3C;
    }
    .plan-link:hover { border-color: #F97316; color: #F97316; }
    .price-card.featured .plan-link {
      background: #F97316; border-color: #F97316; color: #fff;
    }
    .price-card.featured .plan-link:hover { background: #EA580C; }

    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .features-grid { grid-template-columns: repeat(2, 1fr); }
      .how-steps { grid-template-columns: repeat(2, 1fr); }
      .how-steps::before { display: none; }
      .pricing-cards { grid-template-columns: 1fr; }
      .price-card.featured { transform: none; }
    }
    @media (max-width: 640px) {
      .hero { padding: 80px 0 60px; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
      .features-grid { grid-template-columns: 1fr; }
      .how-steps { grid-template-columns: 1fr; }
      .testimonial-slide { padding: 0 16px; }
      .testimonial-card { padding: 28px; }
    }
  </style>
