<script>
  /* ===== TESTIMONIAL CAROUSEL ===== */
  const track = document.getElementById('testimonial-track');
  const dots = document.querySelectorAll('.carousel-dot');
  let currentSlide = 0;
  const totalSlides = 3;
  let autoPlayTimer;

  function goToSlide(n) {
    currentSlide = (n + totalSlides) % totalSlides;
    track.style.transform = `translateX(-${currentSlide * 100}%)`;
    dots.forEach((d, i) => d.classList.toggle('active', i === currentSlide));
  }

  function startAutoPlay() {
    autoPlayTimer = setInterval(() => goToSlide(currentSlide + 1), 5000);
  }

  function resetAutoPlay() {
    clearInterval(autoPlayTimer);
    startAutoPlay();
  }

  document.getElementById('carousel-prev').addEventListener('click', () => { goToSlide(currentSlide - 1); resetAutoPlay(); });
  document.getElementById('carousel-next').addEventListener('click', () => { goToSlide(currentSlide + 1); resetAutoPlay(); });
  dots.forEach(d => d.addEventListener('click', () => { goToSlide(parseInt(d.dataset.index)); resetAutoPlay(); }));
  startAutoPlay();

  /* ===== COUNT-UP ANIMATION ===== */
  function animateCountUp(el) {
    const target = parseInt(el.dataset.target);
    const suffix = el.dataset.suffix || '';
    if (!target) return;
    const duration = 2000;
    const start = performance.now();
    function update(now) {
      const elapsed = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - elapsed, 3);
      const val = Math.round(eased * target);
      const formatted = val >= 1000 ? (val >= 1000000 ? (val/1000000).toFixed(0)+'M' : val.toLocaleString()) : val.toString();
      el.textContent = formatted + suffix;
      if (elapsed < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  const statsObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.querySelectorAll('[data-target]').forEach(animateCountUp);
        statsObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });

  document.querySelector('.stats-section') && statsObserver.observe(document.querySelector('.stats-section'));
</script>
