/* ===================================================
   ShiftWise — Shared Styles
   =================================================== */

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0F1E3C;
  --navy-light: #1a3060;
  --orange: #F97316;
  --orange-dark: #EA580C;
  --orange-light: #FB923C;
  --white: #FFFFFF;
  --gray-50: #F8F9FC;
  --gray-100: #F0F2F7;
  --gray-200: #E8EBF0;
  --gray-400: #9CA6B8;
  --gray-500: #6B7A94;
  --gray-700: #3D4F6E;
  --radius-sm: 8px;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow-sm: 0 1px 4px rgba(15,30,60,0.06);
  --shadow: 0 4px 16px rgba(15,30,60,0.1);
  --shadow-lg: 0 12px 40px rgba(15,30,60,0.14);
  --transition: 0.2s ease;
  --font-head: 'Space Grotesk', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--navy);
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5 {
  font-family: var(--font-head);
  line-height: 1.15;
}

a { text-decoration: none; color: inherit; }
img { max-width: 100%; height: auto; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; }

/* ===== CONTAINER ===== */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-family: var(--font-head);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
  border: 2px solid transparent;
  text-decoration: none;
}

.btn-primary {
  background: var(--orange);
  color: #fff;
  border-color: var(--orange);
}
.btn-primary:hover {
  background: var(--orange-dark);
  border-color: var(--orange-dark);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(249,115,22,0.35);
}

.btn-secondary {
  background: transparent;
  color: var(--navy);
  border-color: var(--gray-200);
}
.btn-secondary:hover {
  border-color: var(--orange);
  color: var(--orange);
}

.btn-ghost {
  background: transparent;
  color: var(--navy);
  border: none;
  padding: 12px 16px;
}
.btn-ghost:hover { color: var(--orange); }

.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,0.35);
}
.btn-outline-light:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.6);
}

.btn-lg {
  padding: 16px 32px;
  font-size: 1.05rem;
  border-radius: 10px;
}

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.site-header.scrolled {
  box-shadow: 0 2px 20px rgba(15,30,60,0.1);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 40px;
  height: 72px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-head);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--navy);
  flex-shrink: 0;
  text-decoration: none;
}

.logo-mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px; height: 36px;
  background: var(--orange);
  color: #fff;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-link {
  padding: 8px 14px;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
  text-decoration: none;
}
.nav-link:hover, .nav-link.active {
  color: var(--orange);
  background: rgba(249,115,22,0.07);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 10px;
  background: transparent;
  border: none;
  cursor: pointer;
  margin-left: auto;
}
.hamburger span {
  display: block;
  width: 22px; height: 2px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 0.3s ease;
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile Nav Drawer */
.mobile-nav {
  position: fixed;
  top: 72px; left: 0; right: 0; bottom: 0;
  background: #fff;
  z-index: 999;
  transform: translateX(-100%);
  transition: transform 0.35s cubic-bezier(0.4,0,0.2,1);
  overflow-y: auto;
}
.mobile-nav.open {
  transform: translateX(0);
}
.mobile-nav-inner {
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mobile-nav-link {
  display: block;
  padding: 16px 20px;
  font-family: var(--font-head);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--navy);
  border-radius: 12px;
  transition: all var(--transition);
}
.mobile-nav-link:hover {
  background: var(--gray-50);
  color: var(--orange);
}
.mobile-nav-actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid var(--gray-200);
}
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15,30,60,0.4);
  z-index: 998;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.mobile-overlay.visible {
  opacity: 1;
  pointer-events: all;
}

/* ===== SECTION HEADERS ===== */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
}
.section-label {
  display: inline-block;
  background: rgba(249,115,22,0.1);
  color: var(--orange);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: 100px;
  margin-bottom: 16px;
}
.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  line-height: 1.15;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--gray-500);
  line-height: 1.75;
}

/* ===== PAGE HERO VARIANTS ===== */
.page-hero {
  background: linear-gradient(135deg, #0F1E3C 0%, #1a3060 100%);
  padding: 80px 0;
  text-align: center;
}
.page-hero h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: #fff;
  margin-bottom: 16px;
}
.page-hero p {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.7);
  max-width: 560px;
  margin: 0 auto;
  line-height: 1.75;
}

/* ===== CTA SECTION ===== */
.cta-section {
  background: linear-gradient(135deg, #F97316 0%, #EA580C 100%);
  padding: 80px 0;
}
.cta-inner {
  text-align: center;
  max-width: 680px;
  margin: 0 auto;
}
.cta-inner h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: #fff;
  margin-bottom: 16px;
}
.cta-inner p {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.85);
  margin-bottom: 36px;
}
.cta-inner .btn-primary {
  background: #fff;
  color: var(--orange);
  border-color: #fff;
}
.cta-inner .btn-primary:hover {
  background: rgba(255,255,255,0.9);
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
}

/* ===== FOOTER ===== */
.site-footer {
  background: #0A1628;
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand p {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.7;
  margin-bottom: 16px;
  margin-top: 12px;
}
.footer-contact-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.85rem;
  color: rgba(255,255,255,0.4);
}
.footer-col h4 {
  font-family: var(--font-head);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.35);
  margin-bottom: 16px;
}
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.55);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--orange); }
.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.08);
  font-size: 0.85rem;
  color: rgba(255,255,255,0.3);
}

/* ===== CHECK LIST ===== */
.check-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
}
.check-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.95rem;
  color: var(--gray-700);
  line-height: 1.5;
}
.check-list li::before {
  content: '✓';
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px; height: 20px;
  background: rgba(249,115,22,0.12);
  color: var(--orange);
  border-radius: 50%;
  font-size: 0.7rem;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}

/* ===== FORM STYLES ===== */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.form-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
}
.form-group input,
.form-group select,
.form-group textarea {
  padding: 13px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--navy);
  background: #fff;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  width: 100%;
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--orange);
  box-shadow: 0 0 0 3px rgba(249,115,22,0.12);
}
.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: #EF4444;
  box-shadow: 0 0 0 3px rgba(239,68,68,0.1);
}
.field-error {
  font-size: 0.8rem;
  color: #EF4444;
  font-weight: 500;
  display: none;
}
.field-error.visible { display: block; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr 1fr;
    gap: 32px;
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {
  .nav-links, .nav-actions { display: none; }
  .hamburger { display: flex; }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 28px;
  }
  .footer-brand { grid-column: 1 / -1; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

