.cta-section {
  background: linear-gradient(135deg, #F97316 0%, #EA580C 100%);
  padding: 80px 0;
}
.cta-inner {
  text-align: center;
  max-width: 680px;
  margin: 0 auto;
}
.cta-inner h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: #fff;
