      background: #F8F9FC;
    }
    .feature-detail-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .feature-detail-grid.reverse { direction: rtl; }
    .feature-detail-grid.reverse > * { direction: ltr; }

