      text-transform: uppercase; letter-spacing: 0.1em;
      color: #F97316;
      margin-bottom: 16px;
    }
    .feature-detail h2 {
      font-size: clamp(1.7rem, 3vw, 2.4rem);
      font-weight: 800;
      color: #0F1E3C;
      margin-bottom: 20px;
      line-height: 1.2;
    }
    .feature-detail p {
      font-size: 1.05rem;
      color: #6B7A94;
      line-height: 1.8;
      margin-bottom: 28px;
    }

    /* Visual mock panel */
    .feature-visual {
      background: linear-gradient(135deg, #0F1E3C 0%, #1a3060 100%);
      border-radius: 20px;
      padding: 40px 32px;
      min-height: 340px;
      display: flex;
      flex-direction: column;
      gap: 14px;
      position: relative;
      overflow: hidden;
      box-shadow: 0 24px 60px rgba(15,30,60,0.2);
    }
    .feature-visual::before {
      content: '';
      position: absolute;
      top: -60px; right: -60px;
      width: 200px; height: 200px;
      background: radial-gradient(circle, rgba(249,115,22,0.2), transparent);
      border-radius: 50%;
    }

    /* Schedule visual */
    .sched-header {
      display: flex; justify-content: space-between; align-items: center;
      margin-bottom: 8px;
    }
    .sched-title { color: #fff; font-weight: 700; font-size: 1rem; }
    .sched-badge {
      background: rgba(249,115,22,0.2); color: #FB923C;
      font-size: 0.75rem; font-weight: 600; padding: 3px 10px; border-radius: 100px;
    }
    .sched-row {
      display: flex; align-items: center; gap: 12px;
    }
    .sched-name {
      color: rgba(255,255,255,0.7); font-size: 0.85rem; font-weight: 500;
      min-width: 90px;
    }
    .sched-bar {
      height: 28px; border-radius: 6px;
      background: linear-gradient(90deg, #F97316, #FB923C);
      display: flex; align-items: center; padding: 0 10px;
      font-size: 0.75rem; color: #fff; font-weight: 600;
      flex: 1;
    }
    .sched-bar.b2 { background: linear-gradient(90deg, #3B82F6, #60A5FA); }
    .sched-bar.b3 { background: linear-gradient(90deg, #10B981, #34D399); }
    .sched-bar.b4 { background: linear-gradient(90deg, #8B5CF6, #A78BFA); }

    /* Message visual */
    .msg-bubble {
      border-radius: 12px;
      padding: 12px 16px;
      font-size: 0.85rem;
      max-width: 80%;
    }
    .msg-bubble.sent {
      background: #F97316; color: #fff;
      align-self: flex-end; border-bottom-right-radius: 3px;
    }
    .msg-bubble.recv {
      background: rgba(255,255,255,0.1); color: rgba(255,255,255,0.9);
      border-bottom-left-radius: 3px;
    }
    .msg-meta {
      font-size: 0.7rem; color: rgba(255,255,255,0.4); margin-top: 3px;
    }
    .msg-list { display: flex; flex-direction: column; gap: 12px; }

    /* Compliance visual */
    .alert-card {
      background: rgba(255,255,255,0.07);
      border-radius: 10px;
      padding: 12px 16px;
      display: flex; align-items: center; gap: 12px;
      border-left: 3px solid #F97316;
    }
    .alert-card.green { border-left-color: #10B981; }
    .alert-card.yellow { border-left-color: #F59E0B; }
    .alert-icon { font-size: 1.2rem; }
    .alert-text { font-size: 0.85rem; color: rgba(255,255,255,0.8); line-height: 1.4; }
    .alert-text strong { color: #fff; display: block; }

    /* ===== INTEGRATIONS ===== */
    .integrations-section {
      padding: 100px 0;
      background: #fff;
    }
    .integration-categories {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      margin-top: 60px;
    }
    .integration-card {
      background: #F8F9FC;
      border-radius: 16px;
      padding: 32px 24px;
      border: 2px solid #E8EBF0;
      transition: all 0.2s;
    }
    .integration-card:hover {
      border-color: #F97316;
      background: #fff;
      transform: translateY(-4px);
      box-shadow: 0 12px 32px rgba(15,30,60,0.1);
    }
    .integration-icon {
      font-size: 2rem;
      margin-bottom: 16px;
    }
    .integration-card h3 {
      font-size: 1rem;
      font-weight: 700;
      color: #0F1E3C;
      margin-bottom: 10px;
    }
    .integration-card ul {
      display: flex;
      flex-direction: column;
      gap: 6px;
    }
    .integration-card ul li {
      font-size: 0.875rem;
      color: #6B7A94;
      padding-left: 14px;
      position: relative;
    }
    .integration-card ul li::before {
      content: '·';
      position: absolute;
      left: 4px;
      color: #F97316;
      font-weight: 700;
