<script>
  /* ===== BILLING TOGGLE ===== */
  const btnMonthly = document.getElementById('btn-monthly');
  const btnAnnual = document.getElementById('btn-annual');
  let isAnnual = false;

  const starterMonthly = { dollars: '29', cents: '.99', period: '/month · up to 3 locations' };
  const starterAnnual =  { dollars: '23', cents: '.99', period: '/month, billed annually · up to 3 locations' };
  const premiumMonthly = { dollars: '69', cents: '.99', period: '/month · unlimited locations' };
  const premiumAnnual =  { dollars: '55', cents: '.99', period: '/month, billed annually · unlimited locations' };

  function setAnnual(annual) {
    isAnnual = annual;
    btnMonthly.classList.toggle('active', !annual);
    btnAnnual.classList.toggle('active', annual);
    btnMonthly.setAttribute('aria-pressed', String(!annual));
    btnAnnual.setAttribute('aria-pressed', String(annual));

    const sd = annual ? starterAnnual : starterMonthly;
    const pd = annual ? premiumAnnual : premiumMonthly;

    document.getElementById('starter-price').textContent = sd.dollars;
    document.getElementById('starter-cents').textContent = sd.cents;
    document.getElementById('starter-period').textContent = sd.period;
    document.getElementById('premium-price').textContent = pd.dollars;
    document.getElementById('premium-cents').textContent = pd.cents;
    document.getElementById('premium-period').textContent = pd.period;

    document.getElementById('starter-savings').classList.toggle('visible', annual);
    document.getElementById('premium-savings').classList.toggle('visible', annual);
  }

  btnMonthly.addEventListener('click', () => setAnnual(false));
  btnAnnual.addEventListener('click', () => setAnnual(true));
  btnMonthly.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setAnnual(false); } });
  btnAnnual.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setAnnual(true); } });

  /* ===== FAQ ACCORDION ===== */
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const btn = item.querySelector('.faq-question');
    btn.addEventListener('click', () => {
      const isOpen = item.classList.contains('open');
      // Close all
      faqItems.forEach(i => {
        i.classList.remove('open');
        i.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
      });
      // Open clicked if it was closed
      if (!isOpen) {
        item.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
      }
    });
  });
</script>
