<script>
  /* ===== CONTACT FORM VALIDATION ===== */
  const form = document.getElementById('contact-form');
  const submitBtn = document.getElementById('submit-btn');

  function getVal(id) { return document.getElementById(id).value.trim(); }

  function setFieldError(inputId, errId, hasError) {
    const input = document.getElementById(inputId);
    const err = document.getElementById(errId);
    if (hasError) {
      input.classList.add('error');
      err.classList.add('visible');
    } else {
      input.classList.remove('error');
      err.classList.remove('visible');
    }
    return !hasError;
  }

  function isValidEmail(v) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
  }

  // Live validation on blur
  document.getElementById('full-name').addEventListener('blur', () => {
    setFieldError('full-name', 'err-name', !getVal('full-name'));
  });
  document.getElementById('email').addEventListener('blur', () => {
    setFieldError('email', 'err-email', !isValidEmail(getVal('email')));
  });
  document.getElementById('company').addEventListener('blur', () => {
    setFieldError('company', 'err-company', !getVal('company'));
  });
  document.getElementById('message').addEventListener('blur', () => {
    setFieldError('message', 'err-message', !getVal('message'));
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = getVal('full-name');
    const email = getVal('email');
    const company = getVal('company');
    const message = getVal('message');

    const v1 = setFieldError('full-name', 'err-name', !name);
    const v2 = setFieldError('email', 'err-email', !isValidEmail(email));
    const v3 = setFieldError('company', 'err-company', !company);
    const v4 = setFieldError('message', 'err-message', !message);

    if (!v1 || !v2 || !v3 || !v4) return;

    // Simulate submission
    submitBtn.textContent = 'Sending…';
    submitBtn.disabled = true;
    submitBtn.style.opacity = '0.7';

    setTimeout(() => {
      document.getElementById('form-container').style.display = 'none';
      document.getElementById('form-success').classList.add('visible');
    }, 900);
  });
</script>
